# region: digest
def digest(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: shape
def shape(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(emit(fold(sift(digest(raw)))))

